<script setup>
import { computed,ref } from 'vue';
import ThemeSelect from '../common/ThemeSelect.vue';
import { api } from '../../lib/api.js';
import { appUrl } from '../../lib/navigation.js';
const props=defineProps({isAdmin:Boolean});
const encrypted=ref(true),exportPassword=ref(''),confirmation=ref(''),includeImages=ref(true),includeSettings=ref(false),importPassword=ref(''),document=ref(null),preview=ref(null),kind=ref('backup'),mode=ref('merge'),applySettings=ref(false),selected=ref([]),query=ref(''),busy=ref(false),error=ref(''),notice=ref(''),undoId=ref('');
const visible=computed(()=>preview.value?.entries.filter(item=>`${item.name} ${item.url} ${item.path}`.toLowerCase().includes(query.value.toLowerCase()))||[]);
function download(data,name){const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));const anchor=window.document.createElement('a');anchor.href=url;anchor.download=name;anchor.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
async function exportBackup(){busy.value=true;error.value='';try{if(encrypted.value&&exportPassword.value!==confirmation.value)throw new Error('비밀번호 확인이 일치하지 않습니다.');const data=await api('backups/export',{method:'POST',body:JSON.stringify({encrypted:encrypted.value,password:encrypted.value?exportPassword.value:'',include_images:includeImages.value,include_settings:includeSettings.value})});download(data,`catppuccindock-${encrypted.value?'encrypted-':''}${new Date().toISOString().slice(0,10)}.json`);exportPassword.value='';confirmation.value='';notice.value='백업 파일을 다운로드했어요.';}catch(e){error.value=e.message;}finally{busy.value=false;}}
async function fileChanged(event){error.value='';preview.value=null;document.value=null;importPassword.value='';const file=event.target.files[0];if(!file)return;if(file.size>(kind.value==='browser'?5:384)*1024*1024){error.value='파일 크기가 허용 범위를 초과합니다.';return;}try{const text=await file.text();document.value=kind.value==='browser'?text:JSON.parse(text);}catch{error.value='올바른 JSON 또는 브라우저 북마크 HTML 파일을 선택해 주세요.';}}
async function inspect(){if(!document.value)return;busy.value=true;error.value='';notice.value='';try{preview.value=await api(kind.value==='backup'?'backups/import-preview':'browser-bookmarks/preview',{method:'POST',body:JSON.stringify(kind.value==='backup'?{document:document.value,password:importPassword.value}:{html:document.value})});importPassword.value='';selected.value=preview.value.entries.filter(item=>!item.existing&&!item.duplicate_in_file&&!item.restricted).map(item=>item.id);mode.value='merge';applySettings.value=false;}catch(e){error.value=e.message;}finally{busy.value=false;}}
async function restore(){if(!preview.value)return;if(mode.value==='replace'&&!confirm('현재 내 탭·카테고리·북마크를 이 백업으로 바꿀까요? 현재 구성은 휴지통에 보관됩니다.'))return;busy.value=true;error.value='';try{const data=await api(kind.value==='backup'?'backups/import':'browser-bookmarks/import',{method:'POST',body:JSON.stringify({preview_id:preview.value.preview_id,mode:mode.value,apply_settings:applySettings.value,selected_ids:kind.value==='browser'?selected.value:null})});undoId.value=data.undo_id||'';notice.value=`${data.added}개 북마크를 가져왔어요. 중복 ${data.duplicates}개·권한 없는 공유 링크 ${data.restricted}개는 제외했습니다.`;preview.value=null;document.value=null;}catch(e){error.value=e.message;}finally{busy.value=false;}}
async function undo(){busy.value=true;error.value='';try{await api(`trash/${undoId.value}/restore`,{method:'POST'});undoId.value='';notice.value='복원 전 구성으로 되돌렸어요.';}catch(e){error.value=e.message;}finally{busy.value=false;}}
function changedKind(){document.value=null;preview.value=null;importPassword.value='';query.value='';}
</script>
<template><section class="settings-section"><p v-if="error" class="form-error" role="alert">{{ error }}</p><p v-if="notice" class="form-notice" role="status">{{ notice }} <button v-if="undoId" class="secondary-button" :disabled="busy" @click="undo">복원 되돌리기</button></p>
<div class="settings-card"><h2>JSON 백업 내보내기</h2><p class="settings-description">내 탭·카테고리·북마크의 이름·주소·아이콘·색상·순서·즐겨찾기와 개인 설정을 저장합니다. GIF와 관리자 공통 포털 설정을 포함할 수 있습니다. 계정·비밀번호·2FA·SSO 및 API 인증정보는 포함하지 않습니다.</p><form class="settings-form" @submit.prevent="exportBackup"><label class="checkbox-label"><input v-model="encrypted" type="checkbox" />비밀번호로 백업 암호화</label><template v-if="encrypted"><label>백업 비밀번호<input v-model="exportPassword" type="password" required minlength="12" maxlength="256" autocomplete="new-password" /><small>12자 이상 입력하세요. 이 비밀번호가 있어야 가져올 수 있습니다.</small></label><label>백업 비밀번호 확인<input v-model="confirmation" type="password" required minlength="12" maxlength="256" autocomplete="new-password" /></label></template><label class="checkbox-label"><input v-model="includeImages" type="checkbox" />업로드한 GIF·아이콘 포함</label><label v-if="isAdmin" class="checkbox-label"><input v-model="includeSettings" type="checkbox" />공통 포털 설정 포함</label><button class="primary-button" :disabled="busy">{{ busy?'처리 중…':'JSON 내보내기' }}</button><a class="secondary-button" :href="appUrl('api/browser-bookmarks/export')" download="bookmarks.html">브라우저용 HTML 내보내기</a></form></div>
<div class="settings-card"><h2>백업 복원 · 브라우저 북마크 가져오기</h2><form class="settings-form" @submit.prevent="inspect"><label>파일 종류<ThemeSelect v-model="kind" label="가져올 파일 종류" :disabled="busy" @change="changedKind" :options="[{value:'backup',label:'CatppuccinDock JSON 백업'},{value:'browser',label:'Chrome·Firefox 북마크 HTML'}]" /></label><label>{{ kind==='backup'?'백업 JSON 파일':'브라우저 북마크 HTML 파일' }}<input :key="kind" type="file" :accept="kind==='backup'?'.json,application/json':'.html,.htm,text/html'" :disabled="busy" @change="fileChanged" /></label><label v-if="kind==='backup'&&document?.format==='CatppuccinDock.encrypted'">가져오기 비밀번호<input v-model="importPassword" type="password" required maxlength="256" autocomplete="off" /></label><button class="secondary-button" :disabled="busy||!document">내용 미리 보기</button></form></div>
<div v-if="preview" class="settings-card"><h2>가져올 내용 확인</h2><p class="settings-description">탭 {{ preview.tabs }}개 · 카테고리 {{ preview.categories }}개 · 북마크 {{ preview.bookmarks }}개 · GIF {{ preview.images }}개 · 업로드 아이콘 {{ preview.icons || 0 }}개 · 중복 {{ preview.duplicates }}개 · 제외 대상 {{ preview.restricted+preview.skipped }}개. 미리 보기는 10분 동안 유효합니다.</p><div class="settings-form"><label v-if="kind==='backup'">복원 방식<ThemeSelect v-model="mode" label="복원 방식" :disabled="busy" :options="[{value:'merge',label:'현재 구성에 병합 · 중복 URL 제외'},{value:'replace',label:'백업 구성으로 덮어쓰기 · 현재 구성은 휴지통 보관'}]" /></label><label v-if="isAdmin&&preview.has_settings" class="checkbox-label"><input v-model="applySettings" type="checkbox" />백업의 공통 포털 설정 적용</label><label>가져올 북마크 검색<input v-model="query" type="search" /></label></div><div class="import-entry-list"><label v-for="item in visible" :key="item.id" class="import-entry"><input v-if="kind==='browser'" v-model="selected" type="checkbox" :value="item.id" :disabled="busy||item.existing||item.duplicate_in_file||item.restricted" /><span><strong>{{ item.name }}</strong><small>{{ item.path }} · {{ item.url }}</small></span><small v-if="item.restricted">공유 권한 없음</small><small v-else-if="item.existing||item.duplicate_in_file">{{ mode==='replace'&&kind==='backup'?'백업에 포함':'중복' }}</small></label></div><button class="primary-button" :disabled="busy||(kind==='browser'&&!selected.length)" @click="restore">{{ kind==='browser'?`선택한 ${selected.length}개 가져오기`:'이 백업으로 복원' }}</button></div>
</section></template>
